package org.synqoria.scheduling;
import org.synqoria.security.TrustedAccessContext;import java.time.*;import java.util.*;
public class AppointmentReschedulePreflightTest{public static void main(String[]a){int n=0;var t=UUID.randomUUID();var f=UUID.randomUUID();var p=UUID.randomUUID();var r=UUID.randomUUID();var now=Instant.parse("2026-11-01T00:00:00Z");var w=new AppointmentWindow(now.plusSeconds(3600),now.plusSeconds(5400),ZoneId.of("UTC"));var v=new AppointmentWindow(now.plusSeconds(7200),now.plusSeconds(9000),ZoneId.of("UTC"));var b=new AppointmentAggregate(UUID.randomUUID(),t,f,p,r,w,AppointmentAggregate.State.CONFIRMED,2,null);var c=new TrustedAccessContext(t,f,UUID.randomUUID(),Set.of("appointment:manage"),Set.of(p));var s=new AppointmentReschedulePreflight();var idx=new ResourceReservationIndex();idx.reserve(b);var d=s.prepare(c,b,v,2,now,idx);check(d.proposed().revision()==3);n++;check(d.event().aggregateVersion()==3);n++;check(s.prepare(c,b,v,1,now,idx).proposed()==null);n++;check(s.prepare(c,b,w,2,now,idx).outcome()==AppointmentReschedulePreflight.Outcome.INVALID_WINDOW);n++;check(s.prepare(c,b,v,2,now.plusSeconds(7200),idx).proposed()==null);n++;var other=new AppointmentAggregate(UUID.randomUUID(),t,f,p,r,v,AppointmentAggregate.State.CONFIRMED,1,null);idx.reserve(other);check(s.prepare(c,b,v,2,now,idx).outcome()==AppointmentReschedulePreflight.Outcome.RESOURCE_CONFLICT);n++;check(s.prepare(null,b,v,2,now,idx).outcome()==AppointmentReschedulePreflight.Outcome.DENIED_NOT_DISCLOSED);n++;check(s.prepare(c,b.transition(AppointmentAggregate.State.ARRIVED,2,null),v,3,now,idx).outcome()==AppointmentReschedulePreflight.Outcome.INVALID_STATE);n++;System.out.println("PASS "+n+" reschedule assertions");}static void check(boolean b){if(!b)throw new AssertionError();}}
